try:
    import pygame
    _PYGAME_AVAILABLE = True
except ImportError:
    _PYGAME_AVAILABLE = False

def resource_path(relative_path):
    """Get absolute path to resource, works for dev and for PyInstaller .app on Mac/Win/Linux"""
    try:
        base_path = sys._MEIPASS
    except Exception:
        base_path = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base_path, relative_path)


# ---------------------------------------------------------------------------
# CROSS-PLATFORM ICON + LINUX GRAB FIX - PR1ME5
# ---------------------------------------------------------------------------
_ICON_B64_PNG = """"""

_icon_tk_refs = []
_icon_temp_path = None

def _get_icon_temp_png():
    global _icon_temp_path
    import tempfile, os, base64
    if _icon_temp_path and os.path.exists(_icon_temp_path):
        return _icon_temp_path
    try:
        data = base64.b64decode(_ICON_B64_PNG)
        td = os.path.join(tempfile.gettempdir(), "pr1me5")
        os.makedirs(td, exist_ok=True)
        p = os.path.join(td, "PR1ME5_icon.png")
        with open(p, "wb") as f:
            f.write(data)
        _icon_temp_path = p
        return p
    except Exception:
        return None

def _set_windows_app_id():
    if sys.platform != "win32":
        return
    try:
        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("com.pr1me5.game.1.0")
    except Exception:
        pass

def set_window_icon(root):
    try:
        if sys.platform == "win32":
            for cand in [
                resource_path(os.path.join("assets", "icons", "PR1ME5.ico")),
                resource_path("PR1ME5.ico"),
                resource_path(os.path.join("assets", "icons", "PR1ME5.png")),
                os.path.join(getattr(sys, "_MEIPASS", ""), "assets", "icons", "PR1ME5.ico"),
                os.path.join(os.path.dirname(__file__), "assets", "icons", "PR1ME5.ico"),
                os.path.join(os.getcwd(), "assets", "icons", "PR1ME5.ico"),
            ]:
                if cand and os.path.exists(cand):
                    try:
                        root.iconbitmap(cand)
                        break
                    except Exception:
                        pass
        png_path = _get_icon_temp_png()
        if png_path:
            img = tk.PhotoImage(file=png_path)
            _icon_tk_refs.append(img)
            root.iconphoto(True, img)
            try:
                root._pr1me5_icon_ref = img
            except Exception:
                pass
            return img
    except Exception:
        pass
    try:
        img = tk.PhotoImage(data=_ICON_B64_PNG)
        _icon_tk_refs.append(img)
        root.iconphoto(True, img)
        try:
            root._pr1me5_icon_ref = img
        except Exception:
            pass
        return img
    except Exception:
        return None

def _patch_tk_for_icon():
    _orig_Tk = tk.Tk
    def PatchedTk(*a, **kw):
        r = _orig_Tk(*a, **kw)
        set_window_icon(r)
        try:
            r.createcommand('tk::mac::ReopenApplication', lambda: r.deiconify())
        except Exception:
            pass
        return r
    tk.Tk = PatchedTk
    _orig_Toplevel = tk.Toplevel
    def PatchedToplevel(*a, **kw):
        w = _orig_Toplevel(*a, **kw)
        set_window_icon(w)
        return w
    tk.Toplevel = PatchedToplevel
