def _load_embedded_font_windows(font_bytes):
    """Register a font on Windows for this process only, straight from
    memory, via AddFontMemResourceEx. Returns True on success."""
    try:
        num_fonts = ctypes.c_uint32(0)
        buf = ctypes.create_string_buffer(font_bytes, len(font_bytes))
        handle = ctypes.windll.gdi32.AddFontMemResourceEx(
            buf, ctypes.sizeof(buf) - 1, 0, ctypes.byref(num_fonts)
        )
        return bool(handle)
    except Exception:
        return False


def _register_font_linux(font_path):
    """Register a font on Linux for this process only, via fontconfig's
    FcConfigAppFontAddFile. This is the standard mechanism apps use to bundle
    a custom font without installing it system-wide. Returns True on success."""
    try:
        fc = ctypes.CDLL("libfontconfig.so.1")
        fc.FcConfigAppFontAddFile.restype = ctypes.c_int
        fc.FcConfigAppFontAddFile.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        result = fc.FcConfigAppFontAddFile(None, font_path.encode("utf-8"))
        return bool(result)
    except Exception:
        return False


def _register_font_macos(font_path):
    """Register a font on macOS for this process only, via CoreText's
    CTFontManagerRegisterFontsForURL with kCTFontManagerScopeProcess (no
    install, no admin rights, cleared automatically when the app quits).
    Returns True on success."""
    try:
        coretext = ctypes.CDLL(
            "/System/Library/Frameworks/CoreText.framework/CoreText")
        corefoundation = ctypes.CDLL(
            "/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation")

        corefoundation.CFURLCreateFromFileSystemRepresentation.restype = ctypes.c_void_p
        corefoundation.CFURLCreateFromFileSystemRepresentation.argtypes = [
            ctypes.c_void_p, ctypes.c_char_p, ctypes.c_long, ctypes.c_bool
        ]
        path_bytes = font_path.encode("utf-8")
        url = corefoundation.CFURLCreateFromFileSystemRepresentation(
            None, path_bytes, len(path_bytes), False
        )
        if not url:
            return False

        # kCTFontManagerScopeProcess = 1 (this process only; nothing persists
        # after the app quits, and no admin/install prompt is ever shown)
        coretext.CTFontManagerRegisterFontsForURL.restype = ctypes.c_bool
        coretext.CTFontManagerRegisterFontsForURL.argtypes = [
            ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p
        ]
        success = coretext.CTFontManagerRegisterFontsForURL(url, 1, None)

        corefoundation.CFRelease.argtypes = [ctypes.c_void_p]
        corefoundation.CFRelease(url)
        return bool(success)
    except Exception:
        return False


# Temp files for the Linux/macOS registration paths need to outlive this
# function call (the OS reads from them lazily), so we keep them around for
# the life of the process rather than deleting them right away.
_bundled_font_temp_dir = None


def load_bundled_fonts():
    """Register the embedded Comfortaa Regular/Bold faces so Tkinter can
    address them as "Comfortaa", on Windows, macOS, and Linux alike. Call
    this once, before creating the Tk root window or any widget that uses
    Config.FONT*. Returns True if both weights registered successfully."""
    global _bundled_font_temp_dir

    if sys.platform == "win32":
        ok_regular = _load_embedded_font_windows(base64.b64decode(_COMFORTAA_REGULAR_B64))
        ok_bold = _load_embedded_font_windows(base64.b64decode(_COMFORTAA_BOLD_B64))
        return ok_regular and ok_bold

    # Linux's fontconfig and macOS's CoreText both register fonts from a file
    # path rather than a raw memory buffer, so write the embedded bytes out
    # to a temp directory once. The directory (and its contents) live for the
    # lifetime of the process and are cleaned up by the OS afterward.
    try:
        _bundled_font_temp_dir = tempfile.mkdtemp(prefix="primes_game_fonts_")
        regular_path = os.path.join(_bundled_font_temp_dir, "Comfortaa-Regular.otf")
        bold_path = os.path.join(_bundled_font_temp_dir, "Comfortaa-Bold.otf")
        with open(regular_path, "wb") as f:
            f.write(base64.b64decode(_COMFORTAA_REGULAR_B64))
        with open(bold_path, "wb") as f:
            f.write(base64.b64decode(_COMFORTAA_BOLD_B64))
    except Exception:
        return False

    if sys.platform == "darwin":
        ok_regular = _register_font_macos(regular_path)
        ok_bold = _register_font_macos(bold_path)
    else:
        # Linux and other X11/fontconfig-based desktops
        ok_regular = _register_font_linux(regular_path)
        ok_bold = _register_font_linux(bold_path)

    return ok_regular and ok_bold


def _decode_wav(wav_b64):
    try:
        return base64.b64decode(wav_b64)
    except Exception:
        return None


# Decoded once at import time so playback never has to touch the disk.
_MOVE_WAV_BYTES = _decode_wav(_MOVE_WAV_B64)
_ERROR_WAV_BYTES = _decode_wav(_ERROR_WAV_B64)
_CAPTURE_WAV_BYTES = _decode_wav(_CAPTURE_WAV_B64)


# ---------------------------------------------------------------------------
# CROSS-PLATFORM AUDIO (pygame.mixer)
# ---------------------------------------------------------------------------
# winsound (used previously) only exists on Windows, so a Linux/Mac build
# would crash the instant this file was imported. pygame.mixer plays sound
# identically on Windows, Mac, and Linux, and - like the font loading above -
# can play both the recorded wav clips and simple synthesized tones straight
# from memory, so no extra data files need to ship with the build.
# ---------------------------------------------------------------------------

_audio_init_attempted = False
_audio_ready = False
_move_sound = None
_error_sound = None
_capture_sound = None
_tone_cache = {}


def init_audio():
    """Initialize pygame's mixer and preload the recorded sound effects.
    Safe to call more than once - only does real work the first time, and
    never raises, even if there's no audio device available at all."""
    global _audio_init_attempted, _audio_ready
    global _move_sound, _error_sound, _capture_sound

    if _audio_init_attempted:
        return _audio_ready

    _audio_init_attempted = True

    if not _PYGAME_AVAILABLE:
        return False

    try:
        pygame.mixer.init(frequency=44100, size=-16, channels=2, buffer=512)
        _move_sound = pygame.mixer.Sound(io.BytesIO(_MOVE_WAV_BYTES)) if _MOVE_WAV_BYTES else None
        _error_sound = pygame.mixer.Sound(io.BytesIO(_ERROR_WAV_BYTES)) if _ERROR_WAV_BYTES else None
        _capture_sound = pygame.mixer.Sound(io.BytesIO(_CAPTURE_WAV_BYTES)) if _CAPTURE_WAV_BYTES else None
        _audio_ready = True
    except Exception:
        _audio_ready = False

    return _audio_ready


def _generate_tone(frequency, duration_ms, volume=0.4):
    """Synthesize a short sine-wave beep as a pygame Sound - this replaces
    winsound.Beep() for the handful of effects (click/victory/special) that
    were never recorded wav clips. Cached per (frequency, duration) so the
    same tone is only ever generated once."""
    key = (frequency, duration_ms, volume)
    if key in _tone_cache:
        return _tone_cache[key]

    sound = None
    try:
        mixer_info = pygame.mixer.get_init()
        sample_rate = mixer_info[0] if mixer_info else 44100
        channels = mixer_info[2] if mixer_info else 2
        n_samples = max(1, int(sample_rate * duration_ms / 1000))
        amplitude = int(32767 * volume)
        fade_samples = max(1, int(sample_rate * 0.008))

        samples = array.array('h')
        for i in range(n_samples):
            fade = 1.0
            if i < fade_samples:
                fade = i / fade_samples
            elif i > n_samples - fade_samples:
                fade = max(0.0, (n_samples - i) / fade_samples)
            value = int(amplitude * fade * math.sin(2 * math.pi * frequency * i / sample_rate))
            for _ in range(channels):
                samples.append(value)

        sound = pygame.mixer.Sound(buffer=samples.tobytes())
    except Exception:
        sound = None

    _tone_cache[key] = sound
    return sound


