    # (still used as a beep fallback if a wav file below can't be found/played)
    CLICK_SOUNDS = [800, 850, 900]  # Multiple click sounds to avoid repetition
    ERROR_SOUNDS = [400, 350, 450]  # Multiple error sounds
    CAPTURE_SOUNDS = [1200, 1300, 1100]  # Multiple capture sounds
    VICTORY_SOUNDS = [1500, 2000, 1800]  # Victory fanfare
    MOVE_SOUNDS = [600, 650, 700]  # Soft move sounds
    SPECIAL_SOUNDS = [1000, 1500, 1200]  # For golden actions

    # Custom recorded sound effects are embedded directly in this file (see the
    # BUNDLED ASSETS section near the top) and played straight from memory - no
    # file paths needed. The frequency lists above remain only as a beep
    # fallback in case audio playback ever fails on a given machine.

    # Font family registered from the embedded Comfortaa font files at startup
