def main():
    """Main function to start the game directly with main menu"""
    _set_windows_app_id()
    _patch_tk_for_icon()
    if sys.platform == "win32":
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(1)
        except Exception:
            try:
                ctypes.windll.user32.SetProcessDPIAware()
            except Exception:
                pass
    # Register the embedded Comfortaa font faces with Windows before any
    # window/widget is created, so every Config.FONT* reference resolves to
    # the real bundled typeface instead of silently falling back to a
    # system default. (Windows-only trick; harmless no-op elsewhere.)
    load_bundled_fonts()
    # Initialize cross-platform audio (pygame.mixer) and preload the
    # recorded sound effects, before any sound is ever requested.
    init_audio()
    show_main_menu()


if __name__ == "__main__":
    main()
